{"command":"python3 - << 'EOF'
import time, os, hashlib
from cryptography.hazmat.primitives import hashes

data = os.urandom(20000 * 1024)

# warmup
hashlib.sha256(data).digest()
d = hashes.Hash(hashes.SHA256()); d.update(data); d.finalize()

def bench(fn, n=5):
    times = []
    for _ in range(n):
        t0 = time.perf_counter()
        fn()
        times.append(time.perf_counter() - t0)
    return min(times), sum(times)/len(times)

def crypto():
    d = hashes.Hash(hashes.SHA256())
    d.update(data)
    return d.finalize()

def hl():
    return hashlib.sha256(data).digest()

def hl2():
    h = hashlib.sha256()
    h.update(data)
    return h.digest()

print("crypto", bench(crypto))
print("hashlib", bench(hl))
print("hashlib2", bench(hl2))
print("equal", hl() == crypto())

# openssl version
import ssl
print(ssl.OPENSSL_VERSION)
print(hashlib.algorithms_available)
EOF"}

{"command":"mkdir -p /tmp/sha_bench && cat > /tmp/sha_bench/bench.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/sha.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 20 * 1024 * 1024;
    unsigned char *data = malloc(n);
    for (size_t i = 0; i < n; i++) data[i] = (unsigned char)i;
    unsigned char out[32];

    // warmup
    SHA256(data, n, out);

    int iters = 5;
    double t0 = now();
    for (int i = 0; i < iters; i++) SHA256(data, n, out);
    double t1 = now();
    printf("SHA256: %.4f s  %.1f MB/s\n", (t1-t0)/iters, n / ((t1-t0)/iters) / 1e6);

    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_MD_CTX *ctx = EVP_MD_CTX_new();
        EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
        EVP_DigestUpdate(ctx, data, n);
        unsigned int len = 32;
        EVP_DigestFinal_ex(ctx, out, &len);
        EVP_MD_CTX_free(ctx);
    }
    t1 = now();
    printf("EVP:    %.4f s  %.1f MB/s\n", (t1-t0)/iters, n / ((t1-t0)/iters) / 1e6);

    // EVP with one-shot
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_Digest(data, n, out, NULL, EVP_sha256(), NULL);
    }
    t1 = now();
    printf("EVP1:   %.4f s  %.1f MB/s\n", (t1-t0)/iters, n / ((t1-t0)/iters) / 1e6);

    printf("digest %02x%02x%02x%02x\n", out[0], out[1], out[2], out[3]);
    return 0;
}
EOF
clang -O3 -o /tmp/sha_bench/bench /tmp/sha_bench/bench.c -I/usr/local/include -L/usr/local/lib -lcrypto && /tmp/sha_bench/bench"}

