echo "==== go sha256 ===="
cat > sha.go << 'EOF'
package main
import (
  "crypto/sha256"
  "fmt"
  "time"
)
func main() {
  n := 20 * 1024 * 1024
  data := make([]byte, n)
  for i := 0; i < n; i++ { data[i] = byte(i) }
  sha256.Sum256(data)
  iters := 5
  t0 := time.Now()
  var sum [32]byte
  for i := 0; i < iters; i++ { sum = sha256.Sum256(data) }
  dt := time.Since(t0).Seconds() / float64(iters)
  fmt.Printf("go: %.4f s  %.1f MB/s  %02x%02x\n", dt, float64(n)/dt/1e6, sum[0], sum[1])
}
EOF
