{"command":"export TMPDIR="$HOME/sha_bench/cache"
cd "$HOME/sha_bench"
cat > shani_test.c << 'EOF'
#include <stdio.h>
#include <signal.h>
#include <setjmp.h>
#include <stdint.h>
#include <cpuid.h>

static jmp_buf jb;
static void handler(int s) { longjmp(jb, 1); }

int main() {
    unsigned int a,b,c,d;
    __cpuid_count(7, 0, a, b, c, d);
    printf("leaf7 ebx=%08x ecx=%08x edx=%08x\n", b, c, d);
    printf("SHA bit (ebx bit 29): %d\n", (b >> 29) & 1);
    printf("AVX2 bit (ebx bit 5): %d\n", (b >> 5) & 1);
    printf("AVX512F (ebx bit 16): %d\n", (b >> 16) & 1);
    printf("BMI2 (ebx bit 8): %d\n", (b >> 8) & 1);

    signal(SIGILL, handler);
    if (setjmp(jb) == 0) {
        /* sha256rnds2 xmm0, xmm1, xmm2  opcode: 0f 38 cb /r */
        unsigned char scratch[64] = {0};
        __asm__ volatile(
            "movdqu (%0), %%xmm0\n\t"
            "movdqu 16(%0), %%xmm1\n\t"
            "movdqu 32(%0), %%xmm2\n\t"
            "sha256rnds2 %%xmm2, %%xmm1, %%xmm0\n\t"
            :
            : "r"(scratch)
            : "xmm0", "xmm1", "xmm2", "memory"
        );
        printf("SHA-NI instruction EXECUTED successfully!\n");
    } else {
        printf("SHA-NI instruction SIGILL\n");
    }
    return 0;
}
EOF
clang -O2 -msha -o shani_test shani_test.c && ./shani_test
echo exit:$?"}

