{"command":"export TMPDIR="$HOME/sha_bench/cache"
cd "$HOME/sha_bench"
cat > freq.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <time.h>

static inline uint64_t rdtsc() {
    unsigned int lo, hi;
    __asm__ volatile("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}

int main() {
    struct timespec ts;
    uint64_t t0 = rdtsc();
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double start = ts.tv_sec + ts.tv_nsec * 1e-9;
    /* busy wait ~200ms using rdtsc spin mixed with nothing */
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double now = ts.tv_sec + ts.tv_nsec * 1e-9;
        if (now - start > 0.2) break;
    }
    uint64_t t1 = rdtsc();
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double end = ts.tv_sec + ts.tv_nsec * 1e-9;
    double freq = (t1 - t0) / (end - start);
    printf("rdtsc freq: %.3f GHz\n", freq / 1e9);

    /* busy loop to see turbo */
    t0 = rdtsc();
    clock_gettime(CLOCK_MONOTONIC, &ts);
    start = ts.tv_sec + ts.tv_nsec * 1e-9;
    volatile uint64_t x = 0;
    while (1) {
        x += 1;
        if ((x & 0xffff) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            double now = ts.tv_sec + ts.tv_nsec * 1e-9;
            if (now - start > 0.3) break;
        }
    }
    t1 = rdtsc();
    clock_gettime(CLOCK_MONOTONIC, &ts);
    end = ts.tv_sec + ts.tv_nsec * 1e-9;
    freq = (t1 - t0) / (end - start);
    printf("busy rdtsc freq: %.3f GHz  x=%llu\n", freq / 1e9, (unsigned long long)x);
    return 0;
}
EOF
clang -O2 -o freq freq.c && ./freq"}

{"command":"export TMPDIR="$HOME/sha_bench/cache"
cd "$HOME/sha_bench"
cat > mb_bench.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/sha.h>

typedef struct {
    const unsigned char *ptr;
    int blocks;
} SHA256_MB_CTX; /* guess: 16-byte entries? looking at offsets 0, 0x10, 0x20, 0x30 so 16 bytes: ptr + int blocks + pad */

/* From disassembly:
   rsi points to array of 4 descriptors:
     offset 0: ptr (8)
     offset 8: blocks (4)
     offset 16: ptr
     ...
   rdi points to hash state such that rdi+0x80 is the base used as -0x80(%rdi) for first state.
   So the state buffer is 8 * 16 = 128 bytes before the pointer? 
   They do: leaq 0x80(%rdi), %rdi then movdqu -0x80(%rdi) which is original rdi.
   States are 32 bytes each? movdqu loads 16 bytes. There are 8 movdqu from -0x80, -0x60, -0x40, -0x20, 0, 0x20, 0x40, 0x60.
   That's 8*16 = 128 bytes = 4 states * 32 bytes. Layout might be interleaved or sequential.

   Sequential 4x SHA256_CTX would be 4*32 = 128 bytes. The loads are 16-byte chunks sequentially. So rdi points to 128-byte state array of 4 concatenated SHA256 states (8 uint32 each = 32 bytes). Good.
*/

extern void sha256_multi_block(unsigned int *state, void *desc, int num);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static void init_state(unsigned int *st) {
    static const unsigned int iv[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };
    for (int i = 0; i < 4; i++) memcpy(st + i*8, iv, 32);
}

int main() {
    size_t blocks = 4096; /* 256 KB per stream */
    size_t bytes = blocks * 64;
    unsigned char *bufs[4];
    for (int i = 0; i < 4; i++) {
        bufs[i] = aligned_alloc(64, bytes);
        memset(bufs[i], 0x11 * (i+1), bytes);
    }
    /* descriptors: 16 bytes each */
    struct {
        const unsigned char *ptr;
        int blocks;
        int pad;
    } desc[4];
    for (int i = 0; i < 4; i++) {
        desc[i].ptr = bufs[i];
        desc[i].blocks = (int)blocks;
        desc[i].pad = 0;
    }
    unsigned int state[4*8+16];
    init_state(state);

    /* warmup */
    sha256_multi_block(state, desc, 4);

    int iters = 10;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        init_state(state);
        for (int j = 0; j < 4; j++) {
            desc[j].ptr = bufs[j];
            desc[j].blocks = (int)blocks;
        }
        sha256_multi_block(state, desc, 4);
    }
    double t1 = now();
    double total_bytes = 4.0 * bytes * iters;
    printf("multi4: %.4f s/iter  throughput %.1f MB/s\n", (t1-t0)/iters, total_bytes/(t1-t0)/1e6);

    /* compare single openssl */
    unsigned char out[32];
    t0 = now();
    for (int i = 0; i < iters; i++) {
        for (int j = 0; j < 4; j++) SHA256(bufs[j], bytes, out);
    }
    t1 = now();
    printf("serial4: %.4f s/iter  throughput %.1f MB/s\n", (t1-t0)/iters, total_bytes/(t1-t0)/1e6);

    printf("state0: ");
    for (int i = 0; i < 8; i++) printf("%08x", state[i]);
    printf("\n");
    /* reference intermediate state after `blocks` blocks (NO padding) — not a full hash.
       Compute by calling SHA256_Transform in a loop if available. */
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    /* SHA256_Update would add padding at end. We want raw transform. */
    extern void SHA256_Transform(SHA256_CTX *c, const unsigned char *data);
    SHA256_Init(&ctx);
    for (size_t b = 0; b < blocks; b++) SHA256_Transform(&ctx, bufs[0] + b*64);
    printf("ref0:   ");
    for (int i = 0; i < 8; i++) printf("%08x", ctx.h[i]);
    printf("\n");
    return 0;
}
