    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n) { return (x >> n) | (x << (32-n)); }

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

/* Process two consecutive 64-byte blocks. State updated after both. */
static void sha256_2blocks(uint32_t state[8], const uint8_t *data) {
    __m256i w0, w1, w2, w3; /* each holds 8 words? we'll keep W as uint32 and use AVX2 only for schedule of 8 words */
    /* Simpler: compute message schedule for 2 blocks with AVX2 by packing the two blocks
       into 128-bit lanes of ymm (2x independent schedules). */
    const uint32_t *b0 = (const uint32_t *)data;
    const uint32_t *b1 = (const uint32_t *)(data + 64);

    __m128i s0 = _mm_loadu_si128((const __m128i *)b0);
    __m128i s1 = _mm_loadu_si128((const __m128i *)(b0+4));
    __m128i s2 = _mm_loadu_si128((const __m128i *)(b0+8));
    __m128i s3 = _mm_loadu_si128((const __m128i *)(b0+12));
    __m128i t0 = _mm_loadu_si128((const __m128i *)b1);
    __m128i t1 = _mm_loadu_si128((const __m128i *)(b1+4));
    __m128i t2 = _mm_loadu_si128((const __m128i *)(b1+8));
    __m128i t3 = _mm_loadu_si128((const __m128i *)(b1+12));
    const __m128i mask = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    s0 = _mm_shuffle_epi8(s0, mask);
    s1 = _mm_shuffle_epi8(s1, mask);
    s2 = _mm_shuffle_epi8(s2, mask);
    s3 = _mm_shuffle_epi8(s3, mask);
    t0 = _mm_shuffle_epi8(t0, mask);
    t1 = _mm_shuffle_epi8(t1, mask);
    t2 = _mm_shuffle_epi8(t2, mask);
    t3 = _mm_shuffle_epi8(t3, mask);

    /* Interleave into ymm: low 128 = block0, high 128 = block1 */
    __m256i W[16];
    W[0] = _mm256_set_m128i(t0, s0);
    W[1] = _mm256_set_m128i(t1, s1);
    W[2] = _mm256_set_m128i(t2, s2);
    W[3] = _mm256_set_m128i(t3, s3);

    /* Expand schedule. Each ymm lane is independent 4-word groups... 
       SHA-256 sigma0/sigma1 are per-word, so we can do both blocks together
       if we store W as pairs of corresponding words. Let's switch representation:
       We'll just compute schedule in scalar for correctness first but vectorized
       sigma. Actually let's do a cleaner vector schedule:
       Store 8 words of block0 in one ymm and 8 of block1 in another, step by 8.
    */
    uint32_t w0s[64], w1s[64];
    _mm_storeu_si128((__m128i*)w0s, s0);
    _mm_storeu_si128((__m128i*)(w0s+4), s1);
    _mm_storeu_si128((__m128i*)(w0s+8), s2);
    _mm_storeu_si128((__m128i*)(w0s+12), s3);
    _mm_storeu_si128((__m128i*)w1s, t0);
    _mm_storeu_si128((__m128i*)(w1s+4), t1);
    _mm_storeu_si128((__m128i*)(w1s+8), t2);
    _mm_storeu_si128((__m128i*)(w1s+12), t3);

    for (int i = 16; i < 64; i += 8) {
        /* vectorize 8 consecutive sigma computations across both blocks? 
           The dependency is w[i] depends on w[i-16], w[i-15], w[i-7], w[i-2].
           For a run of 8, w[i]..w[i+7] can be computed if we have previous.
           Within the 8, w[i+6] depends on w[i+4] which is in the same window (i+4-2=i+2? wait i+6 depends on w[i+4] which is computed in this window).
           So only the first 2 of each 8 are independent of the window. Not easily 8-wide.
           Do 1 word at a time but for both blocks with SSE (2-wide). That's weak.
           Let's just do scalar schedule for now to measure round cost, then optimize.
        */
        break;
    }
    for (int i = 16; i < 64; i++) {
        uint32_t x = w0s[i-15];
        uint32_t s0v = rotr(x,7) ^ rotr(x,18) ^ (x>>3);
        x = w0s[i-2];
        uint32_t s1v = rotr(x,17) ^ rotr(x,19) ^ (x>>10);
        w0s[i] = w0s[i-16] + s0v + w0s[i-7] + s1v;
        x = w1s[i-15];
        s0v = rotr(x,7) ^ rotr(x,18) ^ (x>>3);
        x = w1s[i-2];
        s1v = rotr(x,17) ^ rotr(x,19) ^ (x>>10);
        w1s[i] = w1s[i-16] + s0v + w1s[i-7] + s1v;
    }

    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + K[i] + w0s[i];
        uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d; state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
    a=state[0]; b=state[1]; c=state[2]; d=state[3]; e=state[4]; f=state[5]; g=state[6]; h=state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + K[i] + w1s[i];
        uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d; state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
    (void)W;
}

static void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = len / 64;
    size_t i = 0;
    while (i + 2 <= nblocks) {
        sha256_2blocks(state, data + i*64);
        i += 2;
    }
    /* remainder blocks + padding via a simple path */
    uint8_t block[128];
    size_t rem_off = i * 64;
    size_t rem = len - rem_off;
    memcpy(block, data + rem_off, rem);
    block[rem] = 0x80;
    size_t pad_len = rem + 1;
    if (pad_len <= 56) {
        memset(block + pad_len, 0, 56 - pad_len);
        uint64_t bits = (uint64_t)len * 8;
        for (int j = 0; j < 8; j++) block[63-j] = (uint8_t)(bits >> (8*j));
        sha256_2blocks(state, block); /* processes 128 bytes — WRONG if only 64 valid. Don't use this. */
    }
    /* fallback: don't use 2block for tail. Implement single block below. */
    (void)pad_len;
}

/* Proper implementation below, ignore the broken tail above. We'll only benchmark full blocks via a dedicated function. */

static void process_all(const uint8_t *data, size_t nblocks, uint32_t state[8]) {
    size_t i = 0;
    while (i + 1 < nblocks) {
        sha256_2blocks(state, data + i*64);
        i += 2;
    }
    if (i < nblocks) {
        uint8_t tmp[128];
        memcpy(tmp, data + i*64, 64);
        memset(tmp+64, 0, 64);
        /* process one real block by using a single-block copy of the round loop */
        uint32_t w[64];
        for (int j = 0; j < 16; j++) {
            w[j] = ((uint32_t)tmp[j*4]<<24)|((uint32_t)tmp[j*4+1]<<16)|((uint32_t)tmp[j*4+2]<<8)|tmp[j*4+3];
        }
        for (int j = 16; j < 64; j++) {
            uint32_t x = w[j-15];
            uint32_t s0 = rotr(x,7)^rotr(x,18)^(x>>3);
            x = w[j-2];
            uint32_t s1 = rotr(x,17)^rotr(x,19)^(x>>10);
            w[j] = w[j-16]+s0+w[j-7]+s1;
        }
        uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
        for (int j = 0; j < 64; j++) {
            uint32_t S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
            uint32_t ch = (e&f)^(~e&g);
            uint32_t t1 = h+S1+ch+K[j]+w[j];
            uint32_t S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
            uint32_t maj = (a&b)^(a&c)^(b&c);
            h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+S0+maj;
        }
        state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d; state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
    }
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 8*1024*1024;
    uint8_t *data = aligned_alloc(64, n);
    for (size_t i = 0; i < n; i++) data[i] = (uint8_t)i;
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    process_all(data, n/64, state);
    int iters = 3;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
        process_all(data, n/64, st);
        state[0]=st[0];
    }
    double t1 = now();
    printf("avx2-ish: %.4f s  %.1f MB/s  state %08x\n", (t1-t0)/iters, n/((t1-t0)/iters)/1e6, state[0]);
    return 0;
}
