{"command":"export TMPDIR="$HOME/sha_bench/cache"
cd "$HOME/sha_bench"
cat > parallel_sha.c << 'EOF'
/*
 * Parallel SHA-256 via Merkle-Damgard state splitting.
 *
 * SHA256 compression is a chain. Given IV and message blocks, the state after
 * block i depends on state after block i-1. To parallelize:
 *
 * We precompute, for a fixed chunk size C blocks, the affine-like effect of
 * hashing C blocks is NOT linear, so we cannot precompute a transfer function
 * independent of data.
 *
 * BUT: we can compute the chain in parallel if we use a "deferred start":
 * Thread k starts from the standard IV and hashes its chunk, producing an
 * intermediate state S_k that is NOT the correct chained state.
 * That doesn't help.
 *
 * Correct parallelization requires the starting state of chunk k, which is the
 * ending state of chunk k-1. That's a serial dependency. No way around it
 * for a single message.
 *
 * UNLESS we use the "hash tree" which is a different function. Not allowed.
 *
 * This file instead benchmarks: how fast can 4 threads each run OpenSSL SHA256
 * on independent data (upper bound on parallel throughput).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct {
    unsigned char *data;
    size_t len;
    unsigned char out[32];
} job;

static void *worker(void *arg) {
    job *j = arg;
    EVP_Digest(j->data, j->len, j->out, NULL, EVP_sha256(), NULL);
    return NULL;
}

int main() {
    int nthreads = 4;
    size_t n = 20 * 1024 * 1024;
    unsigned char *data = malloc(n);
    memset(data, 0xab, n);
    int iters = 5;

    /* serial */
    unsigned char out[32];
    EVP_Digest(data, n, out, NULL, EVP_sha256(), NULL);
    double t0 = now();
    for (int i = 0; i < iters; i++) EVP_Digest(data, n, out, NULL, EVP_sha256(), NULL);
    double t1 = now();
