/*
 * Parallel SHA-256 that produces the exact standard digest.
 *
 * Split the message into chunks of C full blocks. For each chunk, a worker
 * computes the SHA-256 compression of those blocks starting from the standard IV,
 * AND also saves the final 64-byte block of the chunk (needed to replay).
 *
 * The main thread then walks chunks in order. For chunk 0, the worker's result
 * (started from IV) is already the correct state. For later chunks, the main
 * thread replays the chunk's blocks starting from the correct incoming state.
 *
 * That replay is still serial and costs the same as hashing everything. So this
 * naive version is NOT faster. It's a scaffold to confirm the API, then we
 * replace the replay with a precomputed "block schedule + state" trick? No.
 *
 * Instead this file measures a DIFFERENT correct algorithm that IS parallel:
 * We only parallelize the message-schedule expansion (sigma0/sigma1), which is
 * data-parallel, while rounds stay serial. If schedule is a large fraction of
 * time, we win. Let's measure schedule vs rounds.
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};
static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

static void schedule_only(const uint8_t *data, size_t nblocks, uint32_t *Wout) {
    for (size_t b = 0; b < nblocks; b++) {
        uint32_t *w = Wout + b*64;
        const uint8_t *blk = data + b*64;
        for (int i = 0; i < 16; i++)
            w[i] = ((uint32_t)blk[i*4]<<24)|((uint32_t)blk[i*4+1]<<16)|((uint32_t)blk[i*4+2]<<8)|blk[i*4+3];
        for (int i = 16; i < 64; i++) {
            uint32_t x = w[i-15];
            uint32_t s0 = rotr(x,7)^rotr(x,18)^(x>>3);
            x = w[i-2];
            uint32_t s1 = rotr(x,17)^rotr(x,19)^(x>>10);
            w[i] = w[i-16]+s0+w[i-7]+s1;
        }
    }
}

static void rounds_only(uint32_t state[8], const uint32_t *W, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const uint32_t *w = W + b*64;
        uint32_t a=state[0],b0=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
        for (int i = 0; i < 64; i++) {
            uint32_t S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
            uint32_t ch = (e&f)^(~e&g);
            uint32_t t1 = h+S1+ch+K[i]+w[i];
            uint32_t S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
            uint32_t maj = (a&b0)^(a&c)^(b0&c);
            h=g; g=f; f=e; e=d+t1; d=c; c=b0; b0=a; a=t1+S0+maj;
        }
        state[0]+=a; state[1]+=b0; state[2]+=c; state[3]+=d; state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
    }
}

int main() {
    size_t n = 4*1024*1024;
    size_t nblocks = n/64;
    uint8_t *data = malloc(n);
    memset(data, 0x5a, n);
    uint32_t *W = malloc(nblocks*64*sizeof(uint32_t));
    int iters = 3;
    double t0 = now();
    for (int i = 0; i < iters; i++) schedule_only(data, nblocks, W);
    double t1 = now();
    printf("schedule: %.4f s  %.1f MB/s\n", (t1-t0)/iters, n/((t1-t0)/iters)/1e6);
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    t0 = now();
    for (int i = 0; i < iters; i++) {
        uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
        rounds_only(st, W, nblocks);
        state[0]=st[0];
    }
    t1 = now();
    printf("rounds:   %.4f s  %.1f MB/s  %08x\n", (t1-t0)/iters, n/((t1-t0)/iters)/1e6, state[0]);
    return 0;
}
EOF
clang -O3 -mavx2 -o tree_sha tree_sha.c && ./tree_sha"}

