#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static inline __m256i rotr_epi32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}

/* Expand schedule for 8 independent blocks at once (8-way SIMD).
   Input: 8 pointers to 64-byte blocks.
   Output: W[64] where each lane is one block's word. */
static void schedule8(const uint8_t *blocks[8], uint32_t W[64][8]) {
    /* Load 16 words x 8 blocks. */
    for (int i = 0; i < 16; i++) {
        uint32_t tmp[8];
        for (int b = 0; b < 8; b++) {
            const uint8_t *p = blocks[b] + i*4;
            tmp[b] = ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];
        }
        __m256i v = _mm256_loadu_si256((const __m256i*)tmp);
        _mm256_storeu_si256((__m256i*)W[i], v);
    }
    for (int i = 16; i < 64; i++) {
        __m256i w15 = _mm256_loadu_si256((const __m256i*)W[i-15]);
        __m256i w2  = _mm256_loadu_si256((const __m256i*)W[i-2]);
        __m256i w16 = _mm256_loadu_si256((const __m256i*)W[i-16]);
        __m256i w7  = _mm256_loadu_si256((const __m256i*)W[i-7]);
        __m256i s0 = _mm256_xor_si256(rotr_epi32(w15, 7), rotr_epi32(w15, 18));
        s0 = _mm256_xor_si256(s0, _mm256_srli_epi32(w15, 3));
        __m256i s1 = _mm256_xor_si256(rotr_epi32(w2, 17), rotr_epi32(w2, 19));
        s1 = _mm256_xor_si256(s1, _mm256_srli_epi32(w2, 10));
        __m256i r = _mm256_add_epi32(w16, s0);
        r = _mm256_add_epi32(r, w7);
        r = _mm256_add_epi32(r, s1);
        _mm256_storeu_si256((__m256i*)W[i], r);
    }
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
    size_t nblocks = 8*1024; /* 512 KB total? 8192*64 = 512KB. Let's do more. */
    nblocks = 64*1024; /* 4 MB, multiple of 8 */
    uint8_t *data = aligned_alloc(64, nblocks*64);
    memset(data, 0x3c, nblocks*64);
    uint32_t (*W)[8] = malloc(64 * 8 * sizeof(uint32_t));
    const uint8_t *ptrs[8];
    int iters = 5;
    /* warmup */
    for (int b = 0; b < 8; b++) ptrs[b] = data + b*64;
    schedule8(ptrs, W);
    double t0 = now();
    for (int it = 0; it < iters; it++) {
        for (size_t b = 0; b < nblocks; b += 8) {
            for (int k = 0; k < 8; k++) ptrs[k] = data + (b+k)*64;
            schedule8(ptrs, W);
        }
    }
    double t1 = now();
    double bytes = (double)nblocks * 64 * iters;
    printf("schedule8: %.4f s  %.1f MB/s  w0=%08x\n", (t1-t0)/iters, (nblocks*64.0)/((t1-t0)/iters)/1e6, W[63][0]);
    return 0;
}
EOF
