/* Hash 8 independent messages of exactly nblocks*64 bytes (no padding here — raw compression from IV). */
static void sha256x8_raw(const uint8_t *blocks[8], size_t nblocks, uint32_t out_state[8][8]) {
    __m256i a = _mm256_set1_epi32(0x6a09e667);
    __m256i b = _mm256_set1_epi32(0xbb67ae85);
    __m256i c = _mm256_set1_epi32(0x3c6ef372);
    __m256i d = _mm256_set1_epi32(0xa54ff53a);
    __m256i e = _mm256_set1_epi32(0x510e527f);
    __m256i f = _mm256_set1_epi32(0x9b05688c);
    __m256i g = _mm256_set1_epi32(0x1f83d9ab);
    __m256i h = _mm256_set1_epi32(0x5be0cd19);

    uint32_t wtmp[8];
    for (size_t blk = 0; blk < nblocks; blk++) {
        __m256i W[64];
        for (int i = 0; i < 16; i++) {
            for (int lane = 0; lane < 8; lane++) {
                const uint8_t *p = blocks[lane] + blk*64 + i*4;
                wtmp[lane] = ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];
            }
            W[i] = _mm256_loadu_si256((const __m256i*)wtmp);
        }
        for (int i = 16; i < 64; i++) {
            __m256i w15 = W[i-15];
            __m256i w2 = W[i-2];
            __m256i s0 = _mm256_xor_si256(rotr(w15,7), rotr(w15,18));
            s0 = _mm256_xor_si256(s0, _mm256_srli_epi32(w15, 3));
            __m256i s1 = _mm256_xor_si256(rotr(w2,17), rotr(w2,19));
            s1 = _mm256_xor_si256(s1, _mm256_srli_epi32(w2, 10));
            __m256i r = _mm256_add_epi32(W[i-16], s0);
            r = _mm256_add_epi32(r, W[i-7]);
            r = _mm256_add_epi32(r, s1);
            W[i] = r;
        }
        __m256i aa=a, bb=b, cc=c, dd=d, ee=e, ff=f, gg=g, hh=h;
        for (int i = 0; i < 64; i++) {
            __m256i S1 = _mm256_xor_si256(rotr(ee,6), rotr(ee,11));
            S1 = _mm256_xor_si256(S1, rotr(ee,25));
            __m256i ch = _mm256_xor_si256(_mm256_and_si256(ee, ff), _mm256_andnot_si256(ee, gg));
            __m256i t1 = _mm256_add_epi32(hh, S1);
            t1 = _mm256_add_epi32(t1, ch);
            t1 = _mm256_add_epi32(t1, _mm256_set1_epi32(K[i]));
            t1 = _mm256_add_epi32(t1, W[i]);
            __m256i S0 = _mm256_xor_si256(rotr(aa,2), rotr(aa,13));
            S0 = _mm256_xor_si256(S0, rotr(aa,22));
            __m256i maj = _mm256_xor_si256(_mm256_and_si256(aa, bb), _mm256_and_si256(aa, cc));
            maj = _mm256_xor_si256(maj, _mm256_and_si256(bb, cc));
            __m256i t2 = _mm256_add_epi32(S0, maj);
            hh=gg; gg=ff; ff=ee; ee=_mm256_add_epi32(dd, t1);
            dd=cc; cc=bb; bb=aa; aa=_mm256_add_epi32(t1, t2);
        }
        a=_mm256_add_epi32(a, aa);
        b=_mm256_add_epi32(b, bb);
        c=_mm256_add_epi32(c, cc);
        d=_mm256_add_epi32(d, dd);
        e=_mm256_add_epi32(e, ee);
        f=_mm256_add_epi32(f, ff);
        g=_mm256_add_epi32(g, gg);
        h=_mm256_add_epi32(h, hh);
    }
    _mm256_storeu_si256((__m256i*)out_state[0], a);
    _mm256_storeu_si256((__m256i*)out_state[1], b);
    _mm256_storeu_si256((__m256i*)out_state[2], c);
    _mm256_storeu_si256((__m256i*)out_state[3], d);
    _mm256_storeu_si256((__m256i*)out_state[4], e);
    _mm256_storeu_si256((__m256i*)out_state[5], f);
    _mm256_storeu_si256((__m256i*)out_state[6], g);
    _mm256_storeu_si256((__m256i*)out_state[7], h);
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
