    printf("got lane0: %08x %08x %08x %08x\n", st[0][0], st[1][0], st[2][0], st[3][0]);
    int ok = ctx.h[0]==st[0][0] && ctx.h[1]==st[1][0] && ctx.h[2]==st[2][0] && ctx.h[3]==st[3][0]
          && ctx.h[4]==st[4][0] && ctx.h[5]==st[5][0] && ctx.h[6]==st[6][0] && ctx.h[7]==st[7][0];
