            __m256i w15 = W[i-15], w2 = W[i-2];
            __m256i s0 = _mm256_xor_si256(_mm256_xor_si256(rotr(w15,7), rotr(w15,18)), _mm256_srli_epi32(w15, 3));
            __m256i s1 = _mm256_xor_si256(_mm256_xor_si256(rotr(w2,17), rotr(w2,19)), _mm256_srli_epi32(w2, 10));
            W[i] = _mm256_add_epi32(_mm256_add_epi32(_mm256_add_epi32(W[i-16], s0), W[i-7]), s1);
        }
        __m256i aa=a, bb=b, cc=c, dd=d, ee=e, ff=f, gg=g, hh=h;
        for (int i = 0; i < 64; i++) {
            __m256i S1 = _mm256_xor_si256(_mm256_xor_si256(rotr(ee,6), rotr(ee,11)), rotr(ee,25));
            __m256i ch = _mm256_xor_si256(_mm256_and_si256(ee, ff), _mm256_andnot_si256(ee, gg));
            __m256i t1 = _mm256_add_epi32(_mm256_add_epi32(_mm256_add_epi32(_mm256_add_epi32(hh, S1), ch), _mm256_set1_epi32(K[i])), W[i]);
            __m256i S0 = _mm256_xor_si256(_mm256_xor_si256(rotr(aa,2), rotr(aa,13)), rotr(aa,22));
            __m256i maj = _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(aa, bb), _mm256_and_si256(aa, cc)), _mm256_and_si256(bb, cc));
            __m256i t2 = _mm256_add_epi32(S0, maj);
            hh=gg; gg=ff; ff=ee; ee=_mm256_add_epi32(dd, t1);
            dd=cc; cc=bb; bb=aa; aa=_mm256_add_epi32(t1, t2);
        }
        a=_mm256_add_epi32(a, aa); b=_mm256_add_epi32(b, bb); c=_mm256_add_epi32(c, cc); d=_mm256_add_epi32(d, dd);
        e=_mm256_add_epi32(e, ee); f=_mm256_add_epi32(f, ff); g=_mm256_add_epi32(g, gg); h=_mm256_add_epi32(h, hh);
    }
    *sink = (uint32_t)_mm256_extract_epi32(a, 0);
}
static void *worker(void *arg) {
    job_t *j = arg;
    const uint8_t *ptrs[8];
    size_t per = j->nblocks; /* nblocks per lane, 8 lanes contiguous */
    for (int i = 0; i < 8; i++) ptrs[i] = j->base + i*per*64;
    sha256x8_raw(ptrs, per, &j->sink);
    return NULL;
}
static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
    int nthreads = 4;
    size_t per_lane_blocks = 4096; /* 256KB per lane */
    size_t bytes_per_thread = per_lane_blocks * 64 * 8;
    size_t total = bytes_per_thread * nthreads;
    uint8_t *data = aligned_alloc(64, total);
    memset(data, 0x11, total);
    pthread_t th[8];
    job_t jobs[8];
    for (int i = 0; i < nthreads; i++) {
        jobs[i].base = data + i*bytes_per_thread;
        jobs[i].nblocks = per_lane_blocks;
    }
    for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    int iters = 4;
    double t0 = now();
    for (int it = 0; it < iters; it++) {
        for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    double t1 = now();
    printf("%d threads sha8: %.4f s  %.1f MB/s  sink=%08x\n", nthreads, (t1-t0)/iters, total/((t1-t0)/iters)/1e6, jobs[0].sink);
    return 0;
}
EOF
