/*
 * Experiment: can we compress a chunk starting from an UNKNOWN state by
 * saving enough info? 
 *
 * SHA-256 compression of one block:
 *   state' = state + Compress(state, block)
 * where Compress depends on state (the rounds mix state into the schedule).
 * So the function f_block(state) = SHA256_Transform(state, block) is a
 * bijection-ish function of state that depends on the block. There is no
 * small "delta" independent of the starting state.
 *
 * Verify empirically that two different start states hashing the same block
 * do not differ by a constant.
 */
#include <stdio.h>
#include <string.h>
#include <openssl/sha.h>

int main() {
    unsigned char blk[64];
    memset(blk, 0x11, 64);
    SHA256_CTX a, b;
    SHA256_Init(&a);
    SHA256_Init(&b);
    b.h[0] ^= 0x1;
    SHA256_Transform(&a, blk);
    SHA256_Transform(&b, blk);
    printf("a0 %08x b0 %08x diff %08x\n", a.h[0], b.h[0], a.h[0]^b.h[0]);
    SHA256_Transform(&a, blk);
    SHA256_Transform(&b, blk);
    printf("a0 %08x b0 %08x diff %08x\n", a.h[0], b.h[0], a.h[0]^b.h[0]);
    return 0;
}
