    int nstreams = 8;
    size_t blocks = 2048; /* 128KB each */
    size_t bytes = blocks * 64;
    unsigned char *bufs[8];
    for (int i = 0; i < nstreams; i++) {
        bufs[i] = aligned_alloc(64, bytes);
        memset(bufs[i], 0x30+i, bytes);
