    struct __attribute__((aligned(64))) {
        const unsigned char *ptr;
        int blocks;
        int pad;
    } desc[8];
    for (int i = 0; i < 8; i++) {
        desc[i].ptr = bufs[i];
        desc[i].blocks = (int)blocks;
        desc[i].pad = 0;
    }

