       i.e. from the pointer we pass. It loads 8 ymm registers = 8*32 = 256 bytes.
       Interleaved: word i of all 8 streams is 32 bytes (8 uint32).
       Layout: state[word * 8 + stream] ? 
       Loads:
         -0x80: ymm8   (32 bytes) = word0 of 8 streams?
         -0x60: ymm9   = word1
         ...
       That's 8 words * 32 bytes = 256 bytes. Yes interleaved by word.
       IV word j goes into bytes [j*32 + stream*4].
    */
    unsigned char *state_mem = aligned_alloc(256, 256 + 256);
    unsigned int *state = (unsigned int *)state_mem;
    static const unsigned int iv[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };
    for (int w = 0; w < 8; w++)
        for (int s = 0; s < 8; s++)
            state[w*8 + s] = iv[w];

    printf("calling...\n"); fflush(stdout);
    sha256_multi_block(state, desc, 1); /* edx>=2 to enter avx2? cmpl $2, %edx; jb scalar. Pass >=2 */
    printf("returned\n");

    /* print stream 0 state: state[w*8 + 0] */
    printf("got0: ");
    for (int w = 0; w < 8; w++) printf("%08x ", state[w*8 + 0]);
    printf("\n");

    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    for (size_t b = 0; b < blocks; b++) SHA256_Transform(&ctx, bufs[0] + b*64);
    printf("ref0: ");
    for (int w = 0; w < 8; w++) printf("%08x ", ctx.h[w]);
    printf("\n");

    int match = 1;
    for (int w = 0; w < 8; w++) if (state[w*8+0] != ctx.h[w]) match = 0;
    printf("match %d\n", match);

    if (match) {
        int iters = 10;
        double t0 = now();
        for (int it = 0; it < iters; it++) {
            for (int w = 0; w < 8; w++)
                for (int s = 0; s < 8; s++)
                    state[w*8 + s] = iv[w];
            for (int i = 0; i < 8; i++) { desc[i].ptr = bufs[i]; desc[i].blocks = (int)blocks; }
            sha256_multi_block(state, desc, 8);
        }
