{"command":"export TMPDIR="$HOME/sha_bench/cache"
cd "$HOME/sha_bench"
# A compact AVX2 SHA-256 message schedule using the well-known 4-word SIMD approach
# from the Intel whitepaper, with scalar rounds using rorx. Measure just this combo.
cat > avx2_sched_scalar_rounds.c << 'EOF'
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

static const uint32_t K[64] __attribute__((aligned(64))) = {
0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROR(x,n) __builtin_rotateright32((x),(n))

/* Intel SHA-256 message schedule, 4 words at a time, SSSE3/AVX. */
static inline __m128i sigma0(__m128i x) {
    /* s0 = rotr(x,7) ^ rotr(x,18) ^ (x>>3) */
    return _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(x, 7), _mm_ror_epi32(x, 18)), _mm_srli_epi32(x, 3));
}
static inline __m128i sigma1(__m128i x) {
    return _mm_xor_si128(_mm_xor_si128(_mm_ror_epi32(x, 17), _mm_ror_epi32(x, 19)), _mm_srli_epi32(x, 10));
}

static void transform(uint32_t st[8], const uint8_t block[64]) {
    const __m128i shuf = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    __m128i w0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)block), shuf);
    __m128i w1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+16)), shuf);
    __m128i w2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+32)), shuf);
    __m128i w3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(block+48)), shuf);
    uint32_t w[64];
    _mm_storeu_si128((__m128i*)w, w0);
    _mm_storeu_si128((__m128i*)(w+4), w1);
    _mm_storeu_si128((__m128i*)(w+8), w2);
    _mm_storeu_si128((__m128i*)(w+12), w3);

    /* vector schedule for remaining words, 4 at a time.
       w[i] = w[i-16] + s0(w[i-15]) + w[i-7] + s1(w[i-2])
       For 4 consecutive, the s1 term depends on words inside the group for the last 2.
       Standard approach computes them with shifts/alignr. We'll do a known-good scalar
       schedule using rorx instead to isolate round performance... actually let's do both
       fused: scalar schedule+rounds interleaved which is what good compilers do.
    */
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    #define ROUND(i) do { \
        if ((i) >= 16) { \
            uint32_t x = w[(i)-15]; \
            uint32_t s0 = ROR(x,7) ^ ROR(x,18) ^ (x>>3); \
            x = w[(i)-2]; \
            uint32_t s1 = ROR(x,17) ^ ROR(x,19) ^ (x>>10); \
            w[i] = w[(i)-16] + s0 + w[(i)-7] + s1; \
        } \
        uint32_t S1 = ROR(e,6) ^ ROR(e,11) ^ ROR(e,25); \
        uint32_t ch = (e & f) ^ (~e & g); \
        uint32_t t1 = h + S1 + ch + K[i] + w[i]; \
        uint32_t S0 = ROR(a,2) ^ ROR(a,13) ^ ROR(a,22); \
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c); \
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+S0+maj; \
    } while(0)
    ROUND(0);ROUND(1);ROUND(2);ROUND(3);ROUND(4);ROUND(5);ROUND(6);ROUND(7);
    ROUND(8);ROUND(9);ROUND(10);ROUND(11);ROUND(12);ROUND(13);ROUND(14);ROUND(15);
    ROUND(16);ROUND(17);ROUND(18);ROUND(19);ROUND(20);ROUND(21);ROUND(22);ROUND(23);
    ROUND(24);ROUND(25);ROUND(26);ROUND(27);ROUND(28);ROUND(29);ROUND(30);ROUND(31);
    ROUND(32);ROUND(33);ROUND(34);ROUND(35);ROUND(36);ROUND(37);ROUND(38);ROUND(39);
    ROUND(40);ROUND(41);ROUND(42);ROUND(43);ROUND(44);ROUND(45);ROUND(46);ROUND(47);
    ROUND(48);ROUND(49);ROUND(50);ROUND(51);ROUND(52);ROUND(53);ROUND(54);ROUND(55);
    ROUND(56);ROUND(57);ROUND(58);ROUND(59);ROUND(60);ROUND(61);ROUND(62);ROUND(63);
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

static void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t n = len/64;
    for (size_t i = 0; i < n; i++) transform(st, data+i*64);
    uint8_t blk[64]; memset(blk,0,64);
    size_t rem = len%64;
    memcpy(blk, data+n*64, rem);
    blk[rem]=0x80;
    if (rem>=56) { transform(st, blk); memset(blk,0,64); }
    uint64_t bits = (uint64_t)len*8;
    for (int j=0;j<8;j++) blk[63-j]=(uint8_t)(bits>>(8*j));
    transform(st, blk);
    for (int i=0;i<8;i++) {
        out[i*4]=st[i]>>24; out[i*4+1]=st[i]>>16; out[i*4+2]=st[i]>>8; out[i*4+3]=st[i];
    }
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
int main(){
    size_t n=8*1024*1024;
    uint8_t *d=aligned_alloc(64,n);
    memset(d,0x42,n);
    uint8_t out[32], ref[32];
    sha256(d,n,out); SHA256(d,n,ref);
    printf("match %d\n", memcmp(out,ref,32)==0);
    int it=3;
    double t0=now(); for(int i=0;i<it;i++) sha256(d,n,out); double t1=now();
    printf("fused: %.1f MB/s\n", n/((t1-t0)/it)/1e6);
    t0=now(); for(int i=0;i<it;i++) SHA256(d,n,ref); t1=now();
    printf("ossl:  %.1f MB/s\n", n/((t1-t0)/it)/1e6);
}
EOF
clang -O3 -march=native -o avx2r avx2_sched_scalar_rounds.c -I/usr/local/include -L/usr/local/lib -lcrypto && ./avx2r"}

